import { IngestPipeline } from "@514labs/moose-lib";

// User Activity Event Data Model
export interface UserActivity {
  event_id: string;
  event_ts: Date;
  user_id: string;
  action: string;
  duration_ms: number; // Nullable in source, defaults to 0
}

// Ingest Pipeline with ClickHouse table optimized for:
// 1. Activity counts per user over date range
// 2. Total duration per action type
export const UserActivityPipeline = new IngestPipeline<UserActivity>("UserActivity", {
  table: {
    orderByFields: ["user_id", "event_ts", "action"]
  },
  stream: true,
  ingestApi: true,
});

