#!/usr/bin/env python3
"""
Script to run verification queries against ClickHouse after data loading
"""
import subprocess
import time

def run_moose_query(sql):
    """Execute SQL query via moose CLI and return result"""
    try:
        result = subprocess.run(['moose', 'query', sql],
                               capture_output=True, text=True, check=True)
        return result.stdout
    except subprocess.CalledProcessError as e:
        print(f"Query failed: {e.stderr}")
        return None

def wait_for_clickhouse(timeout=60):
    """Wait for ClickHouse to be available via moose CLI"""
    start_time = time.time()
    while time.time() - start_time < timeout:
        result = run_moose_query("SELECT 1 as test")
        if result is not None:
            print("ClickHouse is available")
            return True
        time.sleep(2)
    print("Timeout waiting for ClickHouse")
    return False

def run_verification_queries():
    """Run all verification queries from the SQL file"""

    # Read the SQL file
    try:
        with open('/workspace/moose-project/verification_queries.sql', 'r') as f:
            sql_content = f.read()
    except FileNotFoundError:
        print("verification_queries.sql not found")
        return False

    # Split into individual queries (simple split on empty lines)
    queries = []
    current_query = []

    for line in sql_content.split('\n'):
        line = line.strip()
        if not line or line.startswith('--'):
            if current_query:
                queries.append('\n'.join(current_query))
                current_query = []
        else:
            current_query.append(line)

    if current_query:
        queries.append('\n'.join(current_query))

    # Execute each query
    for i, query in enumerate(queries):
        if query.strip():
            print(f"\n=== Verification Query {i+1} ===")
            print(f"Query: {query[:100]}...")
            result = run_moose_query(query)
            if result:
                print("Result:")
                print(result)
            else:
                print("Query failed")

if __name__ == "__main__":
    print("Waiting for ClickHouse to be available...")
    if wait_for_clickhouse():
        print("\nRunning verification queries...")
        run_verification_queries()
    else:
        print("Could not connect to ClickHouse")
